<script setup>import {useForm} from '@inertiajs/vue3'; import {computed,watch} from 'vue'; import AppLayout from '../../Layouts/AppLayout.vue'; const props=defineProps({collaborator:Object,branches:Array,zones:Array,capabilities:Object,editing:Boolean,endpoints:Object}); const form=useForm({name:props.collaborator.user?.name||'',email:props.collaborator.user?.email||'',password:'',password_confirmation:'',code:props.collaborator.code||'',identity_number:props.collaborator.identity_number||'',phone:props.collaborator.phone||'',hired_at:String(props.collaborator.hired_at||'').slice(0,10),branch_id:props.collaborator.branch_id||'',zone_id:props.collaborator.zone_id||'',capabilities:props.collaborator.capabilities||[],status:props.collaborator.status||'active',notes:props.collaborator.notes||''}); const availableZones=computed(()=>props.zones.filter(z=>String(z.branch_id)===String(form.branch_id))); watch(()=>form.branch_id,()=>{if(!availableZones.value.some(z=>String(z.id)===String(form.zone_id)))form.zone_id=''}); const submit=()=>form.transform(d=>props.editing?{...d,_method:'put'}:d).post(props.endpoints.save);</script>
<template><AppLayout :title="editing?'Editar colaborador':'Nuevo colaborador'" eyebrow="Equipo" description="Acceso, ubicación y capacidades operativas."><template #header-actions><a :href="endpoints.index" class="btn-secondary">Volver</a></template><form class="space-y-4" @submit.prevent="submit"><section class="card p-5"><h2 class="font-semibold">Identidad y acceso</h2><div class="mt-4 grid gap-4 md:grid-cols-2 xl:grid-cols-4"><label class="field-label md:col-span-2">Nombre *<input v-model="form.name" class="control" required></label><label class="field-label">Correo *<input v-model="form.email" type="email" class="control" required></label><label class="field-label">Código *<input v-model="form.code" class="control" required></label><label class="field-label">Cédula<input v-model="form.identity_number" class="control"></label><label class="field-label">Teléfono<input v-model="form.phone" class="control"></label><label class="field-label">Contraseña {{editing?'(opcional)':'*'}}<input v-model="form.password" type="password" class="control"></label><label class="field-label">Confirmar contraseña<input v-model="form.password_confirmation" type="password" class="control"></label></div></section><section class="card p-5"><h2 class="font-semibold">Asignación operativa</h2><div class="mt-4 grid gap-4 md:grid-cols-3"><label class="field-label">Sucursal *<select v-model="form.branch_id" class="control"><option value="">Seleccionar</option><option v-for="branch in branches" :key="branch.id" :value="branch.id">{{branch.name}}</option></select></label><label class="field-label">Zona<select v-model="form.zone_id" class="control"><option value="">Sin zona</option><option v-for="zone in availableZones" :key="zone.id" :value="zone.id">{{zone.name}}</option></select></label><label class="field-label">Fecha de contratación<input v-model="form.hired_at" type="date" class="control"></label><label class="field-label">Estado<select v-model="form.status" class="control"><option value="active">Activo</option><option value="inactive">Inactivo</option><option value="suspended">Suspendido</option></select></label></div><fieldset class="mt-5"><legend class="field-label">Capacidades *</legend><div class="mt-3 grid gap-2 sm:grid-cols-2 lg:grid-cols-3"><label v-for="(label,key) in capabilities" :key="key" class="flex items-center gap-2 rounded-lg border p-3 text-xs"><input v-model="form.capabilities" type="checkbox" :value="key">{{label}}</label></div></fieldset><label class="field-label mt-4 block">Notas<textarea v-model="form.notes" class="control"></textarea></label></section><p v-if="Object.keys(form.errors).length" class="text-xs text-rose-600">{{Object.values(form.errors).join(' · ')}}</p><button class="btn-primary">Guardar colaborador</button></form></AppLayout></template>
